#include "ParkingsData.h"
#include "CommonData.h"
#include "main.h"


extern ParkingData_s const ParkingData[];
extern const size_t PARKDATA_SIZE;






volatile int randind = 0;

/*----------------------------------------------------------------------------------------------------------------------*/
/* Generates a random number that is used for selecting parking place.                                                  */
void GenRandParkNumber()
 {
  randind = rand();
 }

/*----------------------------------------------------------------------------------------------------------------------*/
/* Returns a parking places coordinates according a parking number.                                                     */
void GetRandParking(int *ParkingInd, ParkingData_s *Parking)
 {
  int n = randind;
  n %= PARKDATA_SIZE;
  *ParkingInd = n;
  *Parking = ParkingData[n];
 }
















